const fs = await import('node:fs/promises');
const S = "D:\\GitHub\\My-second-brain\\50-知识\\AI工具\\_scripts";
const P2 = "D:\\GitHub\\My-second-brain\\50-知识\\AI工具";
const M = JSON.parse(await fs.readFile(S+"\\_GIG_MASTER_FINAL.json","utf8"));

const REMOVE = ["dribbble.com","ttec.com","arise.com","concentrix.com"];
const EXCLUDED = [];
const newGroups = {};
for (const [cat, items] of Object.entries(M.groups)) {
  const keep = [];
  for (const it of items) {
    const h = String(it.host).toLowerCase().replace(/^www\./,"");
    if (REMOVE.includes(h)) { EXCLUDED.push({name:it.name, host:h, cat, why:"招聘性质强于散活"}); continue; }
    keep.push(it);
  }
  if (keep.length) newGroups[cat] = keep;
}
const total = Object.values(newGroups).reduce((s,g)=>s+g.length,0);
await fs.writeFile(S+"\\_GIG_CLEAN_FINAL.json", JSON.stringify({total, groups:newGroups, excluded:EXCLUDED},null,1), "utf8");
return { total, excluded: EXCLUDED.length, groups: Object.entries(newGroups).map(([k,v])=>k+":"+v.length) };
